<?php
require_once __DIR__.'/../config/auth.php';
if(current_user()){go(current_user()['role']==='owner'?'admin/dashboard.php':'kasir/dashboard.php');}
$error='';$now=time();if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$attemptUsername=safe_substr($username,0,50);$ip=substr((string)($_SERVER['REMOTE_ADDR']??'unknown'),0,45);
 $lockSt=$pdo->prepare('SELECT attempts,locked_until FROM login_attempts WHERE username=?');$lockSt->execute([$attemptUsername]);$lockRow=$lockSt->fetch();
 if($lockRow&&$lockRow['locked_until']&&strtotime($lockRow['locked_until'])>$now){$error='terlalu banyak percobaan. coba lagi setelah '.date('H:i',strtotime($lockRow['locked_until'])).' WIB.';}
 else{
  $st=$pdo->prepare('SELECT id,nama,username,password_hash,role,is_active FROM users WHERE username=? LIMIT 1');$st->execute([$username]);$u=$st->fetch();
  if($u&&(int)$u['is_active']===1&&password_verify($password,$u['password_hash'])){$pdo->prepare('DELETE FROM login_attempts WHERE username=?')->execute([$attemptUsername]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'nama'=>$u['nama'],'username'=>$u['username'],'role'=>$u['role'],'is_active'=>(int)$u['is_active']];log_activity('login','Login berhasil sebagai '.$u['role']);go($u['role']==='owner'?'admin/dashboard.php':'kasir/dashboard.php');}
  else{
   $attempts=($lockRow && empty($lockRow['locked_until']))?(int)$lockRow['attempts']:0;$attempts++;
   if($attempts>=5){$up=$pdo->prepare('INSERT INTO login_attempts (username,attempts,locked_until,last_ip) VALUES (?,5,DATE_ADD(NOW(),INTERVAL 5 MINUTE),?) ON DUPLICATE KEY UPDATE attempts=5,locked_until=DATE_ADD(NOW(),INTERVAL 5 MINUTE),last_ip=VALUES(last_ip),last_attempt=NOW()');$up->execute([$attemptUsername,$ip]);$error='5 kali percobaan gagal. username dikunci selama 5 menit.';}
   else{$up=$pdo->prepare('INSERT INTO login_attempts (username,attempts,locked_until,last_ip) VALUES (?,?,NULL,?) ON DUPLICATE KEY UPDATE attempts=VALUES(attempts),locked_until=NULL,last_ip=VALUES(last_ip),last_attempt=NOW()');$up->execute([$attemptUsername,$attempts,$ip]);$error='username atau password salah. sisa percobaan: '.(5-$attempts).'.';}
  }
 }
}
